
CREATE OR REPLACE TABLE feat AS
SELECT ba, ts_utc, demand, eia_fc, co2_intensity_generated, co2_intensity_consumed, hour(ts_utc) AS hr, dayofweek(ts_utc) AS dow, month(ts_utc) AS mon, dayofyear(ts_utc) AS doy, LAG(demand, 1) OVER w AS y_lag1, LAG(demand, 2) OVER w AS y_lag2, LAG(demand, 3) OVER w AS y_lag3, LAG(demand, 24) OVER w AS y_lag24, LAG(demand, 48) OVER w AS y_lag48, LAG(demand, 168) OVER w AS y_lag168, AVG(demand) OVER (w ROWS BETWEEN 23 PRECEDING AND CURRENT ROW) AS y_ma_season, STDDEV(demand) OVER (w ROWS BETWEEN 23 PRECEDING AND CURRENT ROW) AS y_sd_season, demand - LAG(demand, 1) OVER w AS y_diff1, LAG(co2_intensity_generated, 24) OVER w AS co2_intensity_generated_lag_season, LAG(co2_intensity_consumed, 24) OVER w AS co2_intensity_consumed_lag_season, LEAD(demand, 24) OVER w AS y_h24
FROM clean WINDOW w AS (PARTITION BY ba ORDER BY ts_utc);
